const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Iris -- a macro portrait of the coloured diaphragm of the eye. Radial
// trabecular fibres stream out of the pupil through the pupillary ruff, cross a
// zigzag collarette into the ciliary zone, and are broken by concentric
// contraction furrows and dark Fuchs' crypts, ringed by a dark limbus. The
// pupil breathes -- the pupillary light reflex and hippus dilate and constrict
// it continuously, stretching the whole fibre field -- and a soft corneal
// catchlight drifts across. Photographic, a Vesalius engraving of radial
// hatching, a labelled schematic of the iris zones, or a thermal fibre-density
// map.
// ---------------------------------------------------------------------------
const sd = P.seed | 0;
function hh(ix, iy) { let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd + 11, 1442695041)) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177) | 0; return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
function sstep(t) { return t * t * (3 - 2 * t); }
function vn(x, y) { const xi = Math.floor(x), yi = Math.floor(y), xf = sstep(x - xi), yf = sstep(y - yi); const a = hh(xi, yi), b = hh(xi + 1, yi), c = hh(xi, yi + 1), d = hh(xi + 1, yi + 1); return (a + (b - a) * xf) * (1 - yf) + (c + (d - c) * xf) * yf; }
function fbm(x, y) { return vn(x, y) * 0.58 + vn(x * 2.09 + 4.1, y * 2.09 - 1.7) * 0.28 + vn(x * 4.2 - 3.3, y * 4.2 + 2.2) * 0.14; }
let RR = 0, GG = 0, BB = 0;
function hsv(h, s, v) {
  h = h - Math.floor(h);
  const i = Math.floor(h * 6), f = h * 6 - i, p = v * (1 - s), q = v * (1 - f * s), w = v * (1 - (1 - f) * s);
  if (i === 0) { RR = v; GG = w; BB = p; } else if (i === 1) { RR = q; GG = v; BB = p; }
  else if (i === 2) { RR = p; GG = v; BB = w; } else if (i === 3) { RR = p; GG = q; BB = v; }
  else if (i === 4) { RR = w; GG = p; BB = v; } else { RR = v; GG = p; BB = q; }
}

const BW = Math.max(360, Math.min(680, Math.round(width / 2.5)));
const BH = Math.max(120, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

const style = P.style;
const mag = Math.max(1, P.scale);
const asp = BW / BH;
const ccx = 0.5 + (P.x - 0.5) * 0.3, ccy = 0.5 + (P.y - 0.5) * 0.3;
// pupil breathing: incommensurate slow terms -> never re-phases, never strobes
const breath = 0.5 + 0.5 * (0.6 * Math.sin(K.t * 0.34 + 0.7) + 0.4 * Math.sin(K.t * 0.57 * 1.0 + 2.2));
const rp = (0.10 + P.dilate * 0.18 + breath * 0.09) * (0.9 + A.rms * 0.2);   // pupil radius (frac)
const rColl = rp + 0.10;                                    // collarette radius
const twist = Math.sin(K.t * 0.11) * 0.05;                 // faint stromal shimmer
const gain = 0.72 + P.energy * 0.7 + A.rms * 0.2;
const fib = 0.5 + P.fiber * 1.0, fur = P.furrow;
const gr = P.grain, hbase = P.hue / 360;
// corneal catchlight (drifts)
const clx = ccx + 0.14 + Math.cos(K.t * 0.19) * 0.05, cly = ccy - 0.16 + Math.sin(K.t * 0.23 + 1) * 0.04;

const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    let nx = (i / BW - ccx) / mag, ny = (j / BH - ccy) / mag; nx *= asp;
    const r = Math.sqrt(nx * nx + ny * ny);
    const a = Math.atan2(ny, nx) + twist;
    let R, G, B;
    if (r < rp) {
      // pupil: near black with a faint depth sheen
      const d = r / rp;
      const sh = Math.pow(d, 3) * 0.06;
      R = G = B = 0.02 + sh;
    } else {
      const zr = (r - rp) / (0.62 - rp + 0.001);            // 0 at pupil edge .. 1 outer
      // radial fibres: high angular freq, low radial freq, warped
      const warp = (fbm(Math.cos(a) * 3 + r * 4, Math.sin(a) * 3 - r * 4) - 0.5) * 0.5;
      const fibre = fbm((a + warp) * (26 + P.fiber * 26), r * 5.5 + 3);
      // concentric contraction furrows
      const furrow = 0.5 + 0.5 * Math.sin((r - rp) * 46 + Math.sin(a * 5) * 1.1);
      // crypts near collarette (dark lacunae)
      const crypt = fbm((a + warp) * 9 + 20, zr * 7 - 5);
      const isCrypt = crypt > 0.72 && zr < 0.4;
      // zonal value: dark ruff at pupil, brighter mid, dark limbus
      let val = 0.55 - Math.pow(Math.max(0, 0.14 - (r - rp)) / 0.14, 1.5) * 0.35;   // pupillary ruff dark
      val *= 1 - Math.pow(Math.max(0, r - 0.52) / 0.14, 2) * 0.9;                    // limbal ring darken
      val += (fibre - 0.5) * 0.5 * fib;
      val -= (1 - furrow) * 0.18 * (fur * (0.5 + 0.5 * (1 - zr)));
      if (isCrypt) val -= (crypt - 0.72) * 1.6;
      // collarette ridge highlight (zigzag)
      const zz = rColl + Math.sin(a * 14) * 0.008;
      if (Math.abs(r - zz) < 0.01) val += (0.01 - Math.abs(r - zz)) * 22 * 0.4;
      val = Math.max(0.02, val) * gain;

      if (style === 'engraving') {
        // radial hatching, monochrome plate
        const hatch = 0.5 + 0.5 * Math.sin((a + warp) * 90 + fibre * 4);
        const line = Math.pow(hatch, 2) * (0.6 + zr * 0.4);
        const v = (0.16 + line * 0.7) * (val + 0.3);
        R = v * 0.98; G = v * 0.95; B = v * 0.86;
      } else if (style === 'schematic') {
        // flat labelled zones on a blueprint ground, zone boundaries picked out
        const edge = (Math.abs(r - rColl) < 0.006 || Math.abs(r - 0.5) < 0.006 || Math.abs((a * 8) % 1 - 0.5) < 0.02) ? 1 : 0;
        R = 0.08 + edge * 0.5;
        G = 0.14 + (r < 0.5 ? 0.4 : 0.16) + edge * 0.5;
        B = 0.2 + (r < 0.5 ? 0.5 : 0.2) + edge * 0.6;
      } else if (style === 'thermal') {
        const t2 = Math.max(0, Math.min(1, val * 1.1));
        R = Math.min(1, t2 * 1.8 - 0.2); G = Math.max(0, 1 - Math.abs(t2 - 0.5) * 2.4); B = Math.max(0, 0.7 - t2 * 1.4);
      } else {
        // photo: coloured stroma
        const h = hbase + Math.sin(a * 3) * 0.01 + (fibre - 0.5) * 0.03;
        const s = 0.42 + zr * 0.22 + (fibre - 0.5) * 0.15;
        hsv(h, Math.max(0, Math.min(0.95, s)), Math.max(0, Math.min(1, val * 1.05)));
        R = RR; G = GG; B = BB;
      }
    }
    // corneal catchlight (soft, drifts) — kept low so it never strobes
    const cd = Math.sqrt((nx / asp + ccx - clx) * (nx / asp + ccx - clx) + (ny + ccy - cly) * (ny + ccy - cly));
    const cl = Math.max(0, 1 - cd / 0.11);
    const clv = Math.pow(cl, 2) * 0.5;
    R += clv; G += clv; B += clv;
    // grain
    const nz = (fbm(i * 0.6, j * 0.6) - 0.5) * 0.1 * gr;
    R += nz; G += nz; B += nz;
    // corner vignette
    const vg = 1 - 0.4 * Math.pow(Math.min(1, r / 0.72), 3);
    R *= vg; G *= vg; B *= vg;
    const o = 4 * (j * BW + i);
    px[o] = Math.max(0, Math.min(255, R * 255));
    px[o + 1] = Math.max(0, Math.min(255, G * 255));
    px[o + 2] = Math.max(0, Math.min(255, B * 255));
    px[o + 3] = 255;
  }
}
